---@param jsonData table
function TrailEnterDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    --printInfo("===>>"..table.dump(jsonData))
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            self[key] = checkString(value)
        end
    end
    ---设置rooms相关的数据
    if isSet(jsonData, 'roomRank') then
        self.roomRank = {}
        local rooms = checkTable(jsonData.roomRank)
        local playerDojo = nil
        for i, v in pairs(rooms) do
            ---@type TrailPlayerDojo
            playerDojo = TrailPlayerDojo.New()
            playerDojo.order = i
            playerDojo.posX = 150 + (math.random(1, 150) * (i % 2 == 0 and 1 or -1))
            playerDojo.playerId = checkNumber(v.playerId)
            playerDojo.name = v.name
            playerDojo.avatar = v.avatar
            playerDojo.avatarFrame = v.avatarFrame
            playerDojo.level = checkNumber(v.level)
            playerDojo.score = checkNumber(v.score)
            playerDojo.image = checkNumber(v.image)
            playerDojo.team = checkTable(v.team) ---阵容，key为关卡id {passed = 0, cards = {}, combatValue = xxx, score=评分}
            table.insert(self.roomRank, playerDojo)
        end
    end
    --printInfo("------->>"..table.dump(self.roomRank))

    if isSet(jsonData, 'quests') then
        local rooms = checkTable(jsonData.quests)
        self.quests = {}
        for i, v in pairs(rooms) do
            if checkInt(v) > 0 then
                table.insert(self.quests, checkInt(v))
            end
        end
    end

    if isSet(jsonData, 'tasks') then
        self.tasks = {}
        local rooms = checkTable(jsonData.tasks)
        for i, v in pairs(rooms) do
            if checkInt(v.questId) > 0 then
                table.insert(self.quests, v)
            end
        end
    end
    if isSet(jsonData, "conditions") then
        self.conditions = checkTable(jsonData.conditions)
    end
end

return TrailEnterDojo